		stage("Building menu")
		local createAdapter=parts.adapter(parts.ui,environment)
		local captures={[1]=createAdapter,[2]=data.constantCell,[3]=data.cell(1345),[4]=data.cell(true),[5]=data.cell(60176524)}
		local menu=parts.menu(environment,captures,runtime,factories)(context)
		assert(menu.lib==context.lib,"Menu did not retain its option library")
		context.lib:AddConfigPage()
		if options.Yuji then
			stage("Adding Yuji timing controls")
			local extension=parts.yujiIntegration(parts.yujiController)
			context.yuji=extension.new(environment,context)
			context.yuji:AttachBFC(context.bfc,false)
			for _,tab in ipairs(context.lib.tabs) do
				if tab.name=="Character Autos" then
					local yuki
					for _,group in ipairs(tab.groups) do if group.name=="Yuki" then yuki=group end end
					local newGroup=context.yuji:AttachTab(tab,yuki)
					-- Move the deferred group immediately after Yuki in the same column.
					if yuki then
						newGroup.side=yuki.side
						table.remove(tab.groups,table.find(tab.groups,newGroup))
						table.insert(tab.groups,table.find(tab.groups,yuki)+1,newGroup)
					end
				end
			end
			context.yuji.BfcDelayControl=context.lib.opts.ABFDelay
		end
		context.lib:Open()
		-- Animation observation serves character autos even when auto-block is off.
		context.track.start()
		context.block.start()
		context.lib:ActivateDefaults()
		local player=context.svc.lp
		local characterGeneration=0
		local characterConnection
		local function characterChanged(character)
			characterGeneration+=1
			local generation=characterGeneration
			if characterConnection then characterConnection:Disconnect();characterConnection=nil end
			local function rebind()
				if not context.alive or generation~=characterGeneration or player.Character~=character then return end
				context.svc.cam=environment.workspace.CurrentCamera
				context.lib:RebindCharacter()
			end
			characterConnection=character:GetAttributeChangedSignal("Moveset"):Connect(function() environment.task.defer(rebind) end)
			context.connections[#context.connections+1]=characterConnection
			environment.task.spawn(function()
				local humanoid=character:WaitForChild("Humanoid",10)
				if humanoid and humanoid:WaitForChild("Animator",10) then environment.task.defer(rebind) end
			end)
		end
		context.connections[#context.connections+1]=player.CharacterAdded:Connect(characterChanged)
		if player.Character then characterChanged(player.Character) end
		context.connections[#context.connections+1]=environment.workspace:GetPropertyChangedSignal("CurrentCamera"):Connect(function() context.svc.cam=environment.workspace.CurrentCamera end)
		stage("Menu opened ("..context.variant..")")
		return context
	end,function(problem)
		return environment.debug and environment.debug.traceback and environment.debug.traceback(tostring(problem),2) or tostring(problem)
	end)
	if not ok then
		context.unload()
		environment.warn("[ATOM standalone] Startup failed: "..tostring(result))
		error(result,0)
	end
	return result
end

end)()
local storage=type(getgenv)=="function" and getgenv() or environment
local previous=rawget(storage,"__ATOM_STANDALONE")
if previous and type(previous.unload)=="function" then previous.unload() end
local application=bootstrap({backend=backend,data=data,ui=ui,adapter=adapter,menu=menu},environment,{Yuji=false})
storage.__ATOM_STANDALONE=application
return application
